function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast._timer);toast._timer=setTimeout(()=>t.classList.remove('show'),2600)}
function scientific(node){if(node.level==='species'){const g=node.path.find(x=>x.level==='genus')?.name||'';return `${g} ${node.name.toLowerCase()}`}return node.name}
function resolveNodeId(id){let resolved=id,seen=new Set();while(state?.idAliases?.[resolved]&&!seen.has(resolved)){seen.add(resolved);resolved=state.idAliases[resolved]}return resolved}
function nodeById(id){return state.nodes.find(n=>n.id===resolveNodeId(id))}
function childrenOf(id){return state.nodes.filter(n=>n.parentId===id)}
function normalizeColor(value){const raw=String(value||'').trim();if(/^#[0-9a-f]{6}$/i.test(raw))return raw.toUpperCase();if(/^[0-9a-f]{8}$/i.test(raw))return `#${raw.slice(-6).toUpperCase()}`;if(/^[0-9a-f]{6}$/i.test(raw))return `#${raw.toUpperCase()}`;return '#EFE8DF'}
function originalColorOf(node){return normalizeColor(node?.initialColor||'#EFE8DF')}
function colorOf(node){return normalizeColor(state.colors?.[node?.id]||node?.initialColor||'#EFE8DF')}
function colorInk(color){const hex=normalizeColor(color).slice(1),r=parseInt(hex.slice(0,2),16),g=parseInt(hex.slice(2,4),16),b=parseInt(hex.slice(4,6),16);return (r*299+g*587+b*114)/1000<148?'#FFFFFF':'#2B211C'}
