function renderContextLinks(n){const ancestors=contextAncestors(n);return ancestors.length?`<div class="taxon-list taxon-context">${ancestors.map(a=>`<button data-open="${a.id}"><span>${contextLabel(a)}</span><small>${fieldValue(a,'level')}</small></button>`).join('')}</div>`:''}
function renderContextBlocks(n){const ancestors=contextAncestors(n);if(!ancestors.length)return '';return `<section class="study-context"><div class="context-section-heading"><h2>Contexto taxonómico</h2><p>Información general de niveles superiores; no forma parte de los datos propios de esta ficha.</p></div><div class="context-blocks">${ancestors.map((a,index)=>{const fields=Object.entries(FIELD_LABELS).filter(([key])=>a.fields?.[key]);return `<details class="context-block" ${index===0?'open':''}><summary><span class="context-origin">Información general de</span><button type="button" class="context-title" data-context-open="${a.id}">${contextLabel(a)}</button></summary><div class="context-block-content"><div class="context-fields">${fields.map(([key,label])=>fieldCard(a,key,label,'context')).join('')}</div></div></details>`}).join('')}</div></section>`}
function imagesFor(nodeId){return state.images.filter(i=>i.nodeId===nodeId).sort((a,b)=>(Number(!!b.primary)-Number(!!a.primary))||((a.order??0)-(b.order??0))||String(a.createdAt||'').localeCompare(String(b.createdAt||'')))}
function imageTypeLabel(type){return ({adulto:'Adulto',macho:'Macho',hembra:'Hembra',huevo:'Huevo',larva:'Larva','extremo anterior':'Extremo anterior','extremo posterior':'Extremo posterior','lesión':'Lesión',ciclo:'Ciclo',preparado:'Preparado',esquema:'Esquema',otro:'Otro'})[type]||type||'Otro'}
function renderImages(n,{study=false}={}){const imgs=imagesFor(n.id),galleryClass=`image-gallery-card ${study?'study-gallery':''}`;if(!imgs.length)return state.editMode?`<section class="${galleryClass}"><div class="gallery-head"><div><h2>Galería de imágenes</h2><p class="subtitle">Las imágenes quedan guardadas localmente en este navegador.</p></div></div><button class="image-add-wide" id="addImage">＋<strong>Subir imágenes</strong><small>Seleccioná archivos o arrastralos aquí</small></button></section>`:'<p class="images-empty-note">Sin imágenes cargadas</p>';const [main,...secondary]=imgs;return `<section class="${galleryClass}"><div class="gallery-head"><div><h2>Galería de imágenes</h2><p class="subtitle">${imgs.length} ${imgs.length===1?'imagen':'imágenes'}${state.editMode?' · arrastrá las miniaturas para ordenarlas':''}</p></div>${state.editMode?'<button class="button" id="addImage">Subir imágenes</button>':''}</div><div class="image-feature-layout ${secondary.length||state.editMode?'':'image-single'}"><button class="image-main-tile" data-image="${main.id}"><span class="image-main-visual"><img data-blob="${main.id}" alt="${escapeHtml(main.title||'Imagen principal')}"></span><span class="image-main-caption"><span>Imagen principal · ${escapeHtml(imageTypeLabel(main.type))}</span><strong>${escapeHtml(main.title||'Sin título')}</strong>${main.description?`<small>${escapeHtml(short(main.description))}</small>`:''}</span></button>${secondary.length||state.editMode?`<div class="image-secondary-grid">${secondary.map(i=>`<button class="image-thumb" draggable="${state.editMode?'true':'false'}" data-image="${i.id}" data-image-order="${i.id}" title="${escapeHtml(i.title||imageTypeLabel(i.type))}"><img data-blob="${i.id}" alt="${escapeHtml(i.title||'Imagen de estudio')}"><span>${escapeHtml(i.title||imageTypeLabel(i.type))}</span></button>`).join('')}${state.editMode?'<button class="image-add image-thumb" id="addImageTile">＋<strong>Subir nueva imagen</strong><small>o arrastrar aquí</small></button>':''}</div>`:''}</div></section>`}
function bindDynamic(host,n){
  $$('[data-open]',host).forEach(b=>b.onclick=()=>{if(b.dataset.open==='home'){currentId=state.nodes[0].id}else{currentId=b.dataset.open}render()});$$('[data-open-path]',host).forEach(b=>b.onclick=()=>{const n=nodeById(currentId);const part=n.path.find(p=>p.level===b.dataset.openPath);const idx=n.path.indexOf(part);const id=n.path.slice(0,idx+1).map(p=>`${p.level}:${slug(p.name)}`).join('/');currentId=id;render()});
  $$('[data-context-open]',host).forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();currentId=b.dataset.contextOpen;render()});
  $$('.field-value',host).forEach(el=>el.ondblclick=e=>{e.stopPropagation();editField(el)});$('.scientific-title',host)?.addEventListener('dblclick',e=>{e.stopPropagation();editName(e.currentTarget,n)});$$('.taxon-inline',host).forEach(el=>el.ondblclick=e=>{e.stopPropagation();editTaxon(el,n,el.dataset.taxonomy)});
  $('#addTag',host)?.addEventListener('click',()=>tagModal(n));$$('[data-tag]',host).forEach(b=>b.onclick=()=>state.editMode&&removeTag(n,b.dataset.tag));['#addImage','#addImageTile'].forEach(selector=>$(selector,host)?.addEventListener('click',()=>{$('#filePicker').dataset.node=n.id;$('#filePicker').click()}));$$('[data-add-child]',host).forEach(button=>button.onclick=()=>state.editMode?childModal(n,button.dataset.addChild||null):toast('Activá el modo edición para añadir una ficha'));$('#compareBtn',host)?.addEventListener('click',()=>comparisonModal(n));
  $$('[data-image]',host).forEach(b=>b.onclick=()=>imageModal(state.images.find(i=>i.id===b.dataset.image)));loadImages(host);
  const dz=$('.image-gallery-card',host);if(dz&&state.editMode){['dragenter','dragover'].forEach(e=>dz.addEventListener(e,x=>{if(x.dataTransfer?.types.includes('Files')){x.preventDefault();dz.classList.add('drag')}}));['dragleave','drop'].forEach(e=>dz.addEventListener(e,x=>{if(x.dataTransfer?.types.includes('Files')){x.preventDefault();dz.classList.remove('drag')}}));dz.addEventListener('drop',e=>{const dragged=e.dataTransfer?.getData('text/atlas-image');const target=e.target.closest('[data-image-order]')?.dataset.imageOrder;if(dragged&&target&&dragged!==target)return reorderImages(n.id,dragged,target);if(e.dataTransfer?.files?.length)uploadImages([...e.dataTransfer.files],n.id)});$$('[data-image-order]',host).forEach(tile=>tile.ondragstart=e=>e.dataTransfer.setData('text/atlas-image',tile.dataset.imageOrder))}
}
async function loadImages(scope=document){for(const img of $$('img[data-blob]',scope)){const image=state.images.find(item=>item.id===img.dataset.blob);if(image?.url){img.src=image.url;continue}const blob=await blobGet(img.dataset.blob);if(blob)img.src=URL.createObjectURL(blob)}}
function inlineEdit(el,old,onSave){if(!state.editMode||el.dataset.editing==='true')return;let finished=false,cancelled=false;el.dataset.editing='true';el.contentEditable='true';el.textContent=old;el.focus();document.getSelection()?.selectAllChildren(el);const finish=async(commit)=>{if(finished)return;finished=true;el.contentEditable='false';delete el.dataset.editing;const value=el.textContent.trim();if(!commit||value===old){render();return}await onSave(value)};el.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();cancelled=true;finish(false)}else if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();finish(true)}};el.onblur=()=>finish(!cancelled)}
function taxonomyNode(n,level){const index=n.path.findIndex(part=>part.level===level);if(index<0)return null;return nodeById(n.path.slice(0,index+1).map(part=>`${part.level}:${slug(part.name)}`).join('/'))}
function normalTaxonomyName(level,value){const clean=value.trim();if(level==='species')return clean.toLowerCase();if(level==='genus')return clean?clean[0].toUpperCase()+clean.slice(1):clean;return clean}
async function renameTaxonomy(target,value){const name=normalTaxonomyName(target.level,value);if(!name){toast('El nombre no puede quedar vacío');render();return}if(name===target.name){render();return}const sibling=state.nodes.find(n=>n.id!==target.id&&n.level===target.level&&n.parentId===target.parentId&&n.name.toLowerCase()===name.toLowerCase());if(sibling){toast('Ya existe una ficha con ese nombre en este nivel');render();return}const affected=state.nodes.filter(n=>n.id===target.id||n.id.startsWith(`${target.id}/`)),oldIds=affected.map(n=>n.id);const ids=new Map();const rebuilt=new Map();for(const n of affected){const path=n.path.map(part=>part.level===target.level?{...part,name}:({...part}));const id=path.map(part=>`${part.level}:${slug(part.name)}`).join('/');ids.set(n.id,id);rebuilt.set(n.id,{...n,id,parentId:n.parentId?ids.get(n.parentId)||n.parentId:null,path,name:n.id===target.id?name:n.name,scientificName:n.level==='species'?`${path.find(p=>p.level==='genus')?.name||''} ${n.name.toLowerCase()}`:n.scientificName})}for(const [oldId,newId] of ids){if(oldId!==newId&&state.nodes.some(n=>!ids.has(n.id)&&n.id===newId)){toast('Ese cambio produciría una ficha duplicada');render();return}}for(const [oldId,node] of rebuilt)state.nodes[state.nodes.findIndex(n=>n.id===oldId)]=node;state.images.forEach(image=>{image.nodeId=ids.get(image.nodeId)||image.nodeId});state.colors=Object.fromEntries(Object.entries(state.colors||{}).map(([id,color])=>[ids.get(id)||id,color]));state.idAliases=state.idAliases||{};Object.entries(state.idAliases).forEach(([oldId,current])=>{if(ids.has(current))state.idAliases[oldId]=ids.get(current)});ids.forEach((newId,oldId)=>{if(oldId!==newId)state.idAliases[oldId]=newId});currentId=ids.get(currentId)||currentId;quickId=ids.get(quickId)||quickId;await mutate({type:'taxonomy-rename',id:ids.get(target.id),from:target.name,to:name,affectedIds:[...ids.values()],removedIds:oldIds.filter(oldId=>ids.get(oldId)!==oldId)});toast('Clasificación actualizada')}
async function editField(el){const n=nodeById(el.dataset.node),key=el.dataset.field,old=n.fields?.[key]||'';inlineEdit(el,old,async value=>{n.fields[key]=value;await mutate({type:'field',id:n.id,key,from:old,to:value});toast('Cambio guardado')})}
function editName(el,n){inlineEdit(el,n.name,value=>renameTaxonomy(n,value))}
function editTaxon(el,n,level){const target=taxonomyNode(n,level);if(target)inlineEdit(el,target.name,value=>renameTaxonomy(target,value))}
async function removeTag(n,id){n.tags=(n.tags||[]).filter(x=>x!==id);await mutate({type:'tag-remove',id:n.id,tag:id});toast('Etiqueta quitada')}

function tableRowsFromTaxonomy(){const species=state.nodes.filter(node=>node.level==='species'),generaWithoutSpecies=state.nodes.filter(node=>node.level==='genus'&&!species.some(child=>child.id.startsWith(`${node.id}/`)));return [...species,...generaWithoutSpecies]}
function compareTableValues(left,right){const a=String(left??'').trim(),b=String(right??'').trim();if(a===b)return 0;if(!a)return 1;if(!b)return -1;return a.localeCompare(b,'es',{sensitivity:'base',numeric:true})}
function sortValue(node,key){return key==='scientificName'?scientific(node):fieldValue(node,key)}
function rows(options={}){const q=options.ignoreSearch?'':filters.tableSearch.toLowerCase().trim(),groupFilter=options.ignoreDesktopFilters?'all':filters.group,levelFilter=options.ignoreDesktopFilters?'all':filters.level;return tableRowsFromTaxonomy().filter(n=>{const blob=[n.name,scientific(n),...n.path.map(p=>p.name),...Object.values(n.fields||{}),...(n.tags||[]).map(id=>state.tags.find(t=>t.id===id)?.name||'')].join(' ').toLowerCase();return(!q||blob.includes(q))&&(groupFilter==='all'||pathValue(n,'group')===groupFilter)&&(levelFilter==='all'||n.level===levelFilter)}).sort((a,b)=>{for(const criterion of sortCriteria){const comparison=compareTableValues(sortValue(a,criterion.key),sortValue(b,criterion.key));if(comparison)return comparison*criterion.dir}return 0})}
function resetTaxonomicSort(){sortCriteria=TAXONOMIC_SORT_KEYS.map(key=>({key,dir:1}))}
function promoteSortCriterion(key){const current=sortCriteria.find(criterion=>criterion.key===key);if(current&&sortCriteria[0]?.key===key){sortCriteria=[{key,dir:-current.dir},...sortCriteria.slice(1)];return}sortCriteria=[{key,dir:current?.dir||1},...sortCriteria.filter(criterion=>criterion.key!==key)]}
function sortIndicator(key){const criterion=sortCriteria.find(criterion=>criterion.key===key);if(!criterion)return '';return `<span class="sort-indicator" aria-label="Orden ${criterion.dir===1?'ascendente':'descendente'}">${criterion.dir===1?'↑':'↓'}</span>`}
function visibleColumns(){const visible=state.settings?.visibleColumns||COLUMNS.map(([key])=>key);return COLUMNS.filter(([key])=>visible.includes(key))}
function columnsModal(){const selected=new Set(state.settings?.visibleColumns||COLUMNS.map(([key])=>key)),taxonomic=COLUMNS.filter(([key])=>TAXON_FIELDS.includes(key)),informative=COLUMNS.filter(([key])=>!TAXON_FIELDS.includes(key)),choices=items=>items.map(([key,label])=>`<label class="column-choice"><input type="checkbox" data-visible-column="${key}" ${selected.has(key)?'checked':''}><span>${label}</span></label>`).join('');modal(`<section class="column-modal"><h2>Columnas visibles</h2><p class="subtitle">Ocultá columnas temporalmente; la selección queda guardada en este navegador.</p><div class="column-choice-sections"><section><h3>Clasificación taxonómica</h3><div class="column-choice-grid">${choices(taxonomic)}</div></section><section><h3>Información de estudio</h3><div class="column-choice-grid">${choices(informative)}</div></section></div><div class="modal-actions"><button class="button" id="restoreColumns">Restaurar todas</button><button class="button" data-close-modal>Cancelar</button><button id="saveColumns" class="button primary">Aplicar</button></div></section>`);$('#restoreColumns').onclick=()=>$$('[data-visible-column]').forEach(input=>input.checked=true);$('#saveColumns').onclick=async()=>{const columns=$$('[data-visible-column]').filter(input=>input.checked).map(input=>input.dataset.visibleColumn);if(!columns.length){toast('Dejá al menos una columna visible');return}state.settings.visibleColumns=columns;await persist();await saveSharedPreferences();closeModal();renderTable()}}
function isMobileLayout(){return window.matchMedia('(max-width:700px)').matches}
function rememberTableScroll(){if(isMobileLayout()){mobileScrollTop=window.scrollY;return}const wrap=$('#table')?.querySelector('.table-wrap');if(wrap)tableScroll={top:wrap.scrollTop,left:wrap.scrollLeft}}
function restoreTableScroll(){if(!isMobileLayout())return;requestAnimationFrame(()=>window.scrollTo({top:mobileScrollTop,behavior:'auto'}))}
function mobileExplorerState(){return {atlasMobile:true,screen:'explore',tableSearch:filters.tableSearch,mobileGroups:[...mobileSelectedGroups()],mobileFamilies:[...(filters.mobileFamilies||[])],scrollTop:mobileScrollTop}}
function ensureMobileExplorerHistory(){if(!isMobileLayout()||currentView!=='table')return;history.replaceState({...history.state,...mobileExplorerState()},'',location.href)}
function openMobileFull(node){rememberTableScroll();quickOpen=false;quickId=null;currentId=node.id;currentView='atlas';history.pushState({...history.state,atlasMobile:true,screen:'atlas',nodeId:node.id,tableSearch:filters.tableSearch,mobileGroups:[...mobileSelectedGroups()],mobileFamilies:[...(filters.mobileFamilies||[])],scrollTop:mobileScrollTop},'',location.href);$$('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.view==='atlas'));render()}
function restoreMobileFilters(navigation){filters.tableSearch=navigation.tableSearch||'';const legacyGroup=navigation.mobileGroup&&navigation.mobileGroup!=='all'?[navigation.mobileGroup]:[];filters.mobileGroups=Array.isArray(navigation.mobileGroups)?navigation.mobileGroups:legacyGroup;filters.mobileFamilies=Array.isArray(navigation.mobileFamilies)?navigation.mobileFamilies:[];reconcileMobileFamilies()}
function restoreMobileNavigation(event){const navigation=event.state;if(!isMobileLayout()||!navigation?.atlasMobile)return;restoreMobileFilters(navigation);if(navigation.screen==='atlas'&&nodeById(navigation.nodeId)){mobileScrollTop=Number(navigation.scrollTop)||0;quickOpen=false;quickId=null;currentId=navigation.nodeId;currentView='atlas';$$('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.view==='atlas'));render();return}mobileScrollTop=Number(navigation.scrollTop)||0;quickOpen=false;quickId=null;currentId=null;currentView='table';$$('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.view==='table'));render();restoreTableScroll()}
function closeMobileQuick(){rememberTableScroll();quickOpen=false;quickId=null;renderTable();restoreTableScroll()}
function bindMobileSheetGesture(){const sheet=$('#quickView'),handle=sheet?.querySelector('.mobile-sheet-handle');if(!sheet||!handle||!isMobileLayout())return;let startY=0,offset=0,dragging=false;const reset=()=>{sheet.classList.remove('sheet-dragging');sheet.style.removeProperty('--sheet-drag-y')};handle.addEventListener('pointerdown',event=>{startY=event.clientY;offset=0;dragging=true;sheet.classList.add('sheet-dragging');handle.setPointerCapture?.(event.pointerId);event.preventDefault()});handle.addEventListener('pointermove',event=>{if(!dragging)return;offset=Math.max(0,event.clientY-startY);sheet.style.setProperty('--sheet-drag-y',`${offset}px`)});const finish=event=>{if(!dragging)return;dragging=false;handle.releasePointerCapture?.(event.pointerId);const threshold=Math.max(96,Math.min(180,sheet.offsetHeight*.22));if(offset>=threshold){sheet.classList.remove('sheet-dragging');sheet.classList.add('sheet-dismissed');sheet.style.setProperty('--sheet-drag-y',`${sheet.offsetHeight+40}px`);window.setTimeout(closeMobileQuick,180);return}reset()};handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',()=>{dragging=false;reset()})}
function openQuick(id){const node=nodeById(id);if(!node)return;rememberTableScroll();quickId=node.id;quickOpen=true;currentId=node.id;renderTable();if(!isMobileLayout())requestAnimationFrame(()=>requestAnimationFrame(()=>$('#quickView')?.scrollIntoView({behavior:'smooth',block:'start'})));else restoreTableScroll()}
function quickTitle(n){return n.level==='genus'||n.level==='species'?`<em>${escapeHtml(displayName(n))}</em>`:escapeHtml(displayName(n))}
document.addEventListener('click',e=>{const close=e.target.closest('#quickClose'),complete=e.target.closest('#quickComplete,#quickTitleOpen');if(!close&&!complete)return;e.preventDefault();e.stopImmediatePropagation();if(close){if(isMobileLayout())closeMobileQuick();else{rememberTableScroll();quickOpen=false;renderTable()}return}const n=nodeById(quickId);if(!n)return;if(isMobileLayout()){openMobileFull(n);return}quickOpen=false;currentId=n.id;currentView='atlas';$$('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.view==='atlas'));render()},true);
function isShortTableValue(value){const text=String(value||'').trim();return text.length>0&&text.length<=34&&!text.includes('\n')}
function tableCellClass(n,key){const value=fieldValue(n,key);if(TAXON_FIELDS.includes(key))return 'taxon-cell table-center';if(['ppp','infectiveForm'].includes(key)||(key==='commonName'&&isShortTableValue(value)))return 'table-center';return 'table-left'}
function taxonCellStyle(node){return node?`style="--taxon-bg:${colorOf(node)};--taxon-ink:${colorInk(colorOf(node))}"`:''}
function genusKey(n){return taxonomyNode(n,'genus')?.id||''}
const MOBILE_GROUPS=[
  {id:'all',label:'Todos'},
  {id:'nematodes',label:'Nematodos',matches:n=>pathValue(n,'group')==='NEMATODO'},
  {id:'trematodes',label:'Trematodos',matches:n=>pathValue(n,'group')==='TREMATODO'},
  {id:'cestodes',label:'Cestodos',matches:n=>pathValue(n,'group')==='CESTODO'},
  {id:'arthropods',label:'Artrópodos',matches:n=>pathValue(n,'granGroup')==='ARTRÓPODO'},
  {id:'protozoa',label:'Protozoos',matches:n=>pathValue(n,'granGroup')==='PROTOZOARIOS'}
];
const MOBILE_GROUP_ICONS={
  nematodes:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 16c3-7 7-10 11-8 4 2 1 8-2 7-3-1-1-5 5-6"/></svg>',
  trematodes:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3c5 4 7 8 5 13-1 3-3 5-5 5s-4-2-5-5c-2-5 0-9 5-13Z"/><circle cx="9" cy="10" r="1"/><circle cx="15" cy="10" r="1"/></svg>',
  cestodes:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3c-2 0-3 2-2 4 0 1 1 1 2 1s2 0 2-1c1-2 0-4-2-4Zm0 5v13"/><path d="M9 11h6M9 15h6M9 19h6"/></svg>',
  arthropods:'<svg viewBox="0 0 24 24" aria-hidden="true"><ellipse cx="12" cy="12" rx="3.5" ry="4.5"/><path d="M8.5 8 5 5M8 11H3M8.5 16 5 19M15.5 8 19 5M16 11h5M15.5 16 19 19M12 7V4"/></svg>',
  protozoa:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 10c0-4 4-7 8-6 4 1 5 5 4 9-1 4-4 7-8 7-3 0-5-2-4-5 1-2 2-2 0-5Z"/><circle cx="13" cy="11" r="2"/><path d="m7 7-2-2m1 8-3 1m4 4-2 2"/></svg>'
};
function mobileGroupIcon(id){return MOBILE_GROUP_ICONS[id]?`<span class="mobile-group-icon">${MOBILE_GROUP_ICONS[id]}</span>`:''}
function mobileSelectedGroups(){const valid=new Set(MOBILE_GROUPS.filter(item=>item.id!=='all').map(item=>item.id));const selected=Array.isArray(filters.mobileGroups)?filters.mobileGroups:[];return [...new Set(selected)].filter(id=>valid.has(id))}
function mobileNodeMatchesGroups(node,groups=mobileSelectedGroups()){return !groups.length||groups.some(id=>MOBILE_GROUPS.find(item=>item.id===id)?.matches(node))}
function availableMobileFamilies(){const groups=mobileSelectedGroups();if(!groups.length)return [];return [...new Set(rows({ignoreDesktopFilters:true,ignoreSearch:true}).filter(node=>mobileNodeMatchesGroups(node,groups)).map(node=>pathValue(node,'family')).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es',{sensitivity:'base'}))}
function reconcileMobileFamilies(){const allowed=new Set(availableMobileFamilies());filters.mobileFamilies=[...new Set(Array.isArray(filters.mobileFamilies)?filters.mobileFamilies:[])].filter(family=>allowed.has(family));filters.mobileGroup=mobileSelectedGroups()[0]||'all'}
function toggleMobileGroup(id){if(id==='all'){filters.mobileGroups=[];filters.mobileFamilies=[];filters.mobileGroup='all';return}const selected=new Set(mobileSelectedGroups());selected.has(id)?selected.delete(id):selected.add(id);filters.mobileGroups=[...selected];reconcileMobileFamilies()}
function toggleMobileFamily(family){const selected=new Set(filters.mobileFamilies||[]);selected.has(family)?selected.delete(family):selected.add(family);filters.mobileFamilies=[...selected];reconcileMobileFamilies()}
function mobileSearchMatches(node){const query=filters.tableSearch.toLowerCase().trim();if(!query)return true;const blob=[node.name,scientific(node),...node.path.map(part=>part.name),...Object.values(node.fields||{}),...(node.tags||[]).map(id=>state.tags.find(tag=>tag.id===id)?.name||'')].join(' ').toLowerCase();return blob.includes(query)}
function genusHasOwnStudyContent(node){return node?.level==='genus'&&(node.createdFrom==='app'||Object.values(node.fields||{}).some(value=>String(value||'').trim())||(node.tags||[]).length>0||(node.notes||[]).length>0||imagesFor(node.id).length>0)}
function mobileRows(){const families=new Set(filters.mobileFamilies||[]),visible=rows({ignoreDesktopFilters:true}).filter(node=>mobileNodeMatchesGroups(node)&&(!families.size||families.has(pathValue(node,'family')))),ordered=[],shownGenera=new Set();for(const node of visible){if(node.level==='species'){const genus=taxonomyNode(node,'genus'),genusMatches=genus&&mobileNodeMatchesGroups(genus)&&(!families.size||families.has(pathValue(genus,'family')))&&mobileSearchMatches(genus);if(genus&&genusHasOwnStudyContent(genus)&&genusMatches&&!shownGenera.has(genus.id)){ordered.push({node:genus,hasVisibleSpecies:true});shownGenera.add(genus.id)}ordered.push({node,groupedUnderGenus:shownGenera.has(genus?.id)});continue}ordered.push({node,hasVisibleSpecies:false})}return ordered}
