  $('#modalRoot').innerHTML=`<div class="color-context-menu" role="menu" style="left:${left}px;top:${top}px"><strong>${escapeHtml(displayName(node))}</strong><button id="contextChangeColor" role="menuitem">Cambiar color</button><button id="contextRestoreColor" role="menuitem">Restaurar color original</button></div>`;
  const menu=$('.color-context-menu');
