  modal(`<h2>Personalizar colores</h2><p class="subtitle">1. Elegí un nivel. 2. Elegí la categoría. Cada cambio se aplica a todas sus apariciones.</p><div class="color-levels" role="tablist">${TAXON_FIELDS.map(item=>`<button class="${item===level?'active':''}" data-color-level="${item}" role="tab">${escapeHtml(colorLevelLabel(item))}</button>`).join('')}</div><div class="color-category-picker"><label>Buscar ${escapeHtml(colorLevelLabel(level).toLowerCase())}<input id="colorCategorySearch" placeholder="Buscar…" autocomplete="off"></label><div class="color-category-list" id="colorCategoryList">${items.map(node=>`<button class="color-category ${node.id===selected?.id?'active':''}" data-color-category="${escapeHtml(node.id)}"><span class="color-dot" style="background:${colorOf(node)}"></span><span>${escapeHtml(displayName(node))}</span></button>`).join('')||'<p class="subtitle">No hay categorías en este nivel.</p>'}</div></div>${selected?`<div class="color-selected"><h3>3. Editar categoría</h3><p><strong>${escapeHtml(displayName(selected))}</strong> · ${escapeHtml(colorLevelLabel(selected.level))}</p><div class="color-editor"><label>Color libre<input id="modalColor" type="color" value="${colorOf(selected)}"></label><span class="color-preview" id="colorPreview" style="background:${colorOf(selected)}"></span><output id="colorValue">${colorOf(selected)}</output></div><p class="subtitle">Original/importado: ${originalColorOf(selected)}</p><div class="color-library"><h3>Recientes</h3><div class="recent-colors">${colorSwatches([...new Set((state.recentColors||[]).map(normalizeColor))],'Reciente')}</div><h3>Favoritos</h3><div class="recent-colors">${colorSwatches([...new Set((state.favoriteColors||[]).map(normalizeColor))],'Favorito')}</div></div><div class="modal-actions"><button class="button" id="restoreOriginalColor">Restaurar color original</button><button class="button" id="saveFavoriteColor">Guardar como favorito</button><button class="button" data-close-modal>Cancelar</button><button id="saveColorModal" class="button primary">Aplicar color</button></div></div>`:'<div class="modal-actions"><button class="button" data-close-modal>Cerrar</button></div>'}`);
  $$('[data-color-level]').forEach(button=>button.onclick=()=>colorModal(null,button.dataset.colorLevel));
  const search=$('#colorCategorySearch');if(search)search.oninput=()=>$$('[data-color-category]').forEach(button=>button.hidden=!button.textContent.toLocaleLowerCase('es').includes(search.value.toLocaleLowerCase('es')));
  $$('[data-color-category]').forEach(button=>button.onclick=()=>colorModal(button.dataset.colorCategory,level));
  if(!selected)return;
  const input=$('#modalColor'),preview=$('#colorPreview'),value=$('#colorValue'),updatePreview=()=>{const color=normalizeColor(input.value);preview.style.background=color;value.textContent=color};
  input.oninput=updatePreview;$$('[data-color-swatch]').forEach(button=>button.onclick=()=>{input.value=normalizeColor(button.dataset.colorSwatch);updatePreview()});
  $('#saveFavoriteColor').onclick=async()=>{const color=normalizeColor(input.value);state.favoriteColors=[...new Set([...(state.favoriteColors||[]).map(normalizeColor),color])];await persist();await saveSharedPreferences();colorModal(selected.id,level)};
  $('#restoreOriginalColor').onclick=async()=>{await restoreOriginalColor(selected);closeModal()};
